-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'TESTES DE FRONTEND' and a.numero = 5
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 5 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 05', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 05 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/TESTES-DE-FRONTEND/ATIVIDADES/ATIVIDADE-PRATICA-AULA-05.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga o que é simular (mockar) a API num teste de integração.', 0.2, 'Simular (mockar) a API é trocar o servidor real por uma **resposta falsa controlada pelo teste**: a tela faz a requisição normalmente, mas quem responde é a simulação.', 'Palavras-chave: resposta falsa/simulada; controlada pelo teste; no lugar do servidor real. Nota cheia (0,2): definição completa. Metade (0,1): "usar dados falsos" sem dizer que substitui a API. Zero (0): confunde com apagar a chamada à API.'),
      (v_atividade, 1, 2, 'Cite três motivos pelos quais a API real deixa o teste instável ou difícil de escrever.', 0.4, 'A API real é **lenta**, os **dados mudam** de um dia para o outro, ela pode estar **fora do ar** e **não deixa provocar** um erro 500 (ou 404, ou rede lenta) quando o teste precisa.', 'Palavras-chave: lenta; dados mudam; fora do ar; não dá para provocar erro. Nota cheia (0,4): três motivos corretos. Metade (0,2): dois motivos. Zero (0): um motivo ou nenhum.'),
      (v_atividade, 1, 3, 'Explique o que é um teste instável (flaky) e por que, com a API simulada, o teste controla exatamente o que a API responde.', 0.4, 'Teste **instável (flaky)** é o que **passa ou falha sem que o código tenha mudado**. Com a API simulada, a resposta é **sempre a mesma** e é **escolhida pelo teste** (sucesso, erro, demora), então o resultado só muda se o código da tela mudar.', 'Palavras-chave: passa/falha sem mudar o código; resposta sempre igual; o teste escolhe a resposta. Nota cheia (0,4): definição + por que a simulação resolve. Metade (0,2): só uma das partes. Zero (0): diz que o teste instável é o que sempre falha.'),
      (v_atividade, 2, 1, 'Diga quais são as três formas de simular a API vistas na aula.', 0.2, '**vi.fn()** passado por parâmetro, **vi.spyOn(globalThis, "fetch")** e o **MSW** (Mock Service Worker).', 'Palavras-chave: vi.fn; vi.spyOn no fetch; MSW. Nota cheia (0,2): as três. Metade (0,1): duas. Zero (0): uma ou nenhuma.'),
      (v_atividade, 2, 2, 'Indique a forma certa para cada uma das três situações e justifique cada escolha.', 0.4, '(1) **vi.fn() por parâmetro**: o serviço recebe o cliente, então basta passar um cliente falso (teste unitário). (2) **vi.spyOn(globalThis, "fetch")**: espiona e troca o fetch global num caso simples e pontual. (3) **MSW**: intercepta a requisição de rede, ideal para integração, sem mudar a tela.', 'Palavras-chave: vi.fn para o serviço; spyOn para o caso pontual; MSW para a integração. Nota cheia (0,4): as três correspondências com justificativa. Metade (0,2): duas certas ou as três sem justificativa. Zero (0): uma ou nenhuma.'),
      (v_atividade, 2, 3, 'Explique como o MSW funciona (o que ele intercepta e quem responde) e por que o código da tela não precisa mudar.', 0.4, 'O MSW **intercepta a requisição de rede** (o fetch da tela) e **responde no lugar do servidor**, com a resposta definida no handler. A tela continua chamando o mesmo endereço com o mesmo fetch, por isso o **código da tela não muda**: só a resposta é simulada.', 'Palavras-chave: intercepta a requisição; responde no lugar do servidor; handler; tela sem mudança. Nota cheia (0,4): funcionamento + por que a tela não muda. Metade (0,2): só uma das partes. Zero (0): diz que é preciso trocar o fetch dentro da tela.'),
      (v_atividade, 3, 1, 'Escreva o comando que instala o MSW como dependência de desenvolvimento.', 0.2, 'npm install -D msw', 'Palavras-chave: npm install -D (ou --save-dev) msw. Nota cheia (0,2): comando certo. Metade (0,1): instala sem -D. Zero (0): outro pacote.'),
      (v_atividade, 3, 2, 'Escreva o arquivo src/mocks/handlers.js com a constante URL_API e o handler de POST /login que responde 401 com { erro: "Credenciais inválidas" } ou { nome: "Aluno", token: "mock-jwt-xyz" }.', 0.4, 'import { http, HttpResponse } from ''msw''; export const URL_API = ''http://localhost:3000/api''; export const handlers = [ http.post(URL_API + ''/login'', async ({ request }) => { const { email, senha } = await request.json(); if (email !== ''aluno@senai.br'' || senha !== ''123456'') { return HttpResponse.json({ erro: ''Credenciais inválidas'' }, { status: 401 }); } return HttpResponse.json({ nome: ''Aluno'', token: ''mock-jwt-xyz'' }); }), ];', 'Palavras-chave: import http e HttpResponse; URL_API; http.post da rota /login; request.json(); status 401 com erro; resposta com nome e token. Nota cheia (0,4): handler completo e correto. Metade (0,2): falta o 401 ou a leitura do corpo, ou usa outro método HTTP. Zero (0): sem handler.'),
      (v_atividade, 3, 3, 'Escreva o arquivo src/mocks/servidor.js com o setupServer e explique por que o servidor fica num módulo próprio e por que, no Node, a URL precisa ser completa.', 0.4, 'import { setupServer } from ''msw/node''; import { handlers } from ''./handlers.js''; export const servidor = setupServer(...handlers); — Fica num **módulo próprio** para que o **setup e os testes usem o mesmo servidor** (por exemplo, no servidor.use). No Node, o **fetch precisa de URL completa** (não entende caminho relativo como /api/login), por isso a constante URL_API fica num lugar só.', 'Palavras-chave: setupServer de msw/node; ...handlers; mesmo servidor no setup e nos testes; URL completa no Node. Nota cheia (0,4): código + as duas explicações. Metade (0,2): código sem as explicações, ou explicações sem o código. Zero (0): sem setupServer.'),
      (v_atividade, 4, 1, 'Escreva o beforeAll e o afterAll que ligam e desligam o servidor.', 0.2, 'beforeAll(() => servidor.listen({ onUnhandledRequest: ''error'' })); afterAll(() => servidor.close());', 'Palavras-chave: beforeAll com servidor.listen; afterAll com servidor.close. Nota cheia (0,2): os dois. Metade (0,1): só um. Zero (0): nenhum.'),
      (v_atividade, 4, 2, 'Escreva o afterEach que desfaz as respostas trocadas e limpa o localStorage, e explique para que serve cada linha.', 0.4, 'afterEach(() => { servidor.resetHandlers(); localStorage.clear(); }); — **resetHandlers()** desfaz, depois de cada teste, as respostas trocadas com servidor.use (o próximo teste volta à simulação padrão); **localStorage.clear()** apaga os dados guardados (token, carrinho), para um teste não interferir no outro.', 'Palavras-chave: afterEach; resetHandlers desfaz servidor.use; localStorage.clear isola. Nota cheia (0,4): código + as duas explicações. Metade (0,2): código com uma explicação, ou só uma das linhas. Zero (0): sem afterEach.'),
      (v_atividade, 4, 3, 'Explique o que faz a opção onUnhandledRequest: "error" no servidor.listen e que defeito ela ajuda a encontrar.', 0.4, 'Com **onUnhandledRequest: "error"**, o teste **falha se a tela chamar uma rota que não tem simulação**. Ajuda a encontrar **chamadas esquecidas ou endereços errados** (rota digitada errado, chamada a uma API real que escapou do mock).', 'Palavras-chave: falha com rota sem simulação; rota errada ou esquecida. Nota cheia (0,4): o que faz + o defeito que encontra. Metade (0,2): só uma das partes. Zero (0): diz que esconde os erros.'),
      (v_atividade, 5, 1, 'Escreva uma função auxiliar entrarCom(email, senha) que monta a tela, digita os dois campos e clica em Entrar com o userEvent.', 0.2, 'async function entrarCom(email, senha) { montarTelaLogin(document.body); const usuario = userEvent.setup(); await usuario.type(screen.getByLabelText(''E-mail''), email); await usuario.type(screen.getByLabelText(''Senha''), senha); await usuario.click(screen.getByRole(''button'', { name: ''Entrar'' })); }', 'Palavras-chave: async; montarTelaLogin; userEvent.setup; type com await nos dois campos; click no botão Entrar pelo papel. Nota cheia (0,2): função completa. Metade (0,1): falta o await ou um dos passos. Zero (0): não monta a tela.'),
      (v_atividade, 5, 2, 'Escreva o teste do login aceito, conferindo a mensagem de boas-vindas e o token guardado no localStorage.', 0.4, 'it(''mostra boas-vindas e guarda o token'', async () => { await entrarCom(''aluno@senai.br'', ''123456''); expect(await screen.findByText(''Bem-vindo, Aluno'')).toBeInTheDocument(); expect(localStorage.getItem(''token'')).toBe(''mock-jwt-xyz''); });', 'Palavras-chave: credenciais válidas; await findByText Bem-vindo, Aluno; localStorage.getItem(''token'') toBe mock-jwt-xyz. Nota cheia (0,4): teste completo. Metade (0,2): confere só a mensagem ou só o token. Zero (0): usa a API real ou credenciais inválidas.'),
      (v_atividade, 5, 3, 'Escreva o teste da senha errada, conferindo a mensagem de erro e que nenhum token foi guardado, e explique por que os dois testes usam findByText.', 0.4, 'it(''mostra o erro e não guarda token'', async () => { await entrarCom(''aluno@senai.br'', ''errada''); expect(await screen.findByText(''Credenciais inválidas'')).toBeInTheDocument(); expect(localStorage.getItem(''token'')).toBeNull(); }); — Os dois usam **findByText** porque a mensagem só aparece **depois que a resposta (assíncrona) do fetch chega**; o findBy **espera** a mensagem aparecer.', 'Palavras-chave: senha errada; findByText Credenciais inválidas; token toBeNull; resposta assíncrona. Nota cheia (0,4): teste + explicação. Metade (0,2): teste sem explicação, ou explicação sem conferir o token. Zero (0): usa getByText logo após o clique sem espera.'),
      (v_atividade, 6, 1, 'Explique o que é confiabilidade (4.3) numa tela de front-end.', 0.2, 'Confiabilidade é a tela **continuar útil quando algo dá errado** (servidor fora do ar, erro, rede lenta): mostra uma mensagem clara e deixa o usuário tentar de novo, em vez de quebrar.', 'Palavras-chave: continua útil quando algo dá errado; não quebra; mensagem. Nota cheia (0,2): definição com exemplo de falha. Metade (0,1): definição vaga. Zero (0): confunde com desempenho.'),
      (v_atividade, 6, 2, 'Escreva o servidor.use que faz a rota de login responder 500 só neste teste e o teste que confere a mensagem esperada.', 0.4, 'servidor.use(http.post(URL_API + ''/login'', () => new HttpResponse(null, { status: 500 }))); await entrarCom(''aluno@senai.br'', ''123456''); expect(await screen.findByText(''Serviço indisponível, tente novamente'')).toBeInTheDocument(); expect(screen.getByRole(''button'', { name: ''Entrar'' })).toBeEnabled();', 'Palavras-chave: servidor.use; http.post da rota de login; status 500; findByText da mensagem; botão habilitado. Nota cheia (0,4): simulação + teste com a mensagem (o toBeEnabled é desejável). Metade (0,2): só a simulação ou teste sem servidor.use. Zero (0): altera o handler padrão para todos os testes sem resetHandlers.'),
      (v_atividade, 6, 3, 'A resposta 500 vem sem corpo. Explique o que acontece com resposta.json() na tela atual, por que o teste falha e o que precisa mudar no código da tela.', 0.4, 'Sem corpo, **resposta.json() lança erro**: a função da tela para no meio, nenhuma mensagem aparece (e fica "Carregando..."), por isso o **findByText não encontra** a mensagem e o teste falha. A tela precisa de **try/catch** (ou conferir o status antes do json) e de uma **mensagem própria** para o erro do servidor, reativando o botão.', 'Palavras-chave: json() lança erro; nada aparece; teste falha; try/catch e mensagem própria. Nota cheia (0,4): causa + correção. Metade (0,2): só a causa ou só a correção. Zero (0): diz que o teste está errado e deve ser apagado.'),
      (v_atividade, 7, 1, 'Diga o comportamento esperado da tela no erro 404 e na rede lenta.', 0.2, '**404:** mostrar uma **mensagem amigável, sem quebrar a página**. **Rede lenta:** mostrar **"Carregando..."** enquanto espera e **retirar o aviso quando a resposta chegar**.', 'Palavras-chave: 404 mensagem amigável sem quebrar; rede lenta Carregando... e retirar. Nota cheia (0,2): os dois comportamentos. Metade (0,1): um dos dois. Zero (0): nenhum.'),
      (v_atividade, 7, 2, 'Escreva o servidor.use que simula a rede lenta (delay de 800 ms) e depois responde o login aceito.', 0.4, 'servidor.use(http.post(URL_API + ''/login'', async () => { await delay(800); return HttpResponse.json({ nome: ''Aluno'', token: ''mock-jwt-xyz'' }); })); (com delay importado de msw).', 'Palavras-chave: servidor.use; http.post /login; await delay(800); HttpResponse.json com nome e token. Nota cheia (0,4): simulação completa. Metade (0,2): falta o delay ou a resposta. Zero (0): usa setTimeout no teste em vez de simular na API.'),
      (v_atividade, 7, 3, 'Escreva o teste da rede lenta que confere "Carregando..." logo depois do clique e, em seguida, a mensagem de boas-vindas sem tempo fixo.', 0.4, 'await entrarCom(''aluno@senai.br'', ''123456''); expect(screen.getByText(''Carregando...'')).toBeInTheDocument(); expect(await screen.findByText(''Bem-vindo, Aluno'')).toBeInTheDocument(); (também vale conferir que "Carregando..." saiu com waitForElementToBeRemoved ou queryByText.)', 'Palavras-chave: Carregando... logo após o clique; findByText da boas-vindas; sem setTimeout. Nota cheia (0,4): as duas conferências sem tempo fixo. Metade (0,2): só uma das conferências. Zero (0): espera com tempo fixo.'),
      (v_atividade, 8, 1, 'Explique os dois problemas da espera com tempo fixo.', 0.2, 'O tempo fixo deixa o teste **lento quando sobra** (espera 2 s mesmo que a resposta chegue antes) e **intermitente (flaky) quando falta** (num computador mais lento a resposta demora mais que 2 s e o teste falha).', 'Palavras-chave: lento quando sobra; intermitente/flaky quando falta. Nota cheia (0,2): os dois problemas. Metade (0,1): um. Zero (0): nenhum.'),
      (v_atividade, 8, 2, 'Reescreva a espera da mensagem "Bem-vindo, Aluno" e a espera do botão Entrar voltar a ficar habilitado, sem tempo fixo.', 0.4, 'expect(await screen.findByText(''Bem-vindo, Aluno'')).toBeInTheDocument(); — await waitFor(() => expect(screen.getByRole(''button'', { name: ''Entrar'' })).toBeEnabled());', 'Palavras-chave: await findByText; await waitFor com expect toBeEnabled. Nota cheia (0,4): as duas esperas certas. Metade (0,2): uma das duas. Zero (0): mantém setTimeout.'),
      (v_atividade, 8, 3, 'Escreva a espera de que o aviso "Carregando..." saia da tela e explique como findBy e waitFor funcionam (tentativas e limite).', 0.4, 'await waitForElementToBeRemoved(() => screen.queryByText(''Carregando...'')); — O findBy e o waitFor **tentam de novo várias vezes** até a condição dar certo ou até o **limite de tempo (1 s por padrão)**; se passar do limite, o teste falha com a mensagem do último erro.', 'Palavras-chave: waitForElementToBeRemoved com queryByText; tenta de novo; limite de 1 s. Nota cheia (0,4): código + funcionamento. Metade (0,2): só o código ou só o funcionamento. Zero (0): espera fixa.'),
      (v_atividade, 9, 1, 'Explique por que o segundo teste encontra os produtos do primeiro.', 0.2, 'O **localStorage não é limpo entre os testes**: o que o primeiro teste guardou **continua lá** quando o segundo começa.', 'Palavras-chave: localStorage não é limpo; dados do teste anterior continuam. Nota cheia (0,2): causa certa. Metade (0,1): "um teste interfere no outro" sem citar o armazenamento. Zero (0): culpa o MSW.'),
      (v_atividade, 9, 2, 'Escreva o teste que adiciona um produto e confere, lendo o localStorage com JSON.parse, que o carrinho tem 1 item com o nome certo.', 0.4, 'it(''guarda o produto no carrinho'', () => { adicionarAoCarrinho({ nome: ''Mouse'' }); const carrinho = JSON.parse(localStorage.getItem(''carrinho'')); expect(carrinho).toHaveLength(1); expect(carrinho[0].nome).toBe(''Mouse''); });', 'Palavras-chave: adicionarAoCarrinho; JSON.parse(localStorage.getItem(''carrinho'')); toHaveLength(1); nome certo. Nota cheia (0,4): teste completo. Metade (0,2): confere só a quantidade ou só o nome, ou esquece o JSON.parse. Zero (0): não lê o localStorage.'),
      (v_atividade, 9, 3, 'Diga onde fica o localStorage.clear() que garante o isolamento e explique por que cada teste precisa começar com o armazenamento vazio.', 0.4, 'No **afterEach do tests/setup.js** (ou do arquivo de teste): afterEach(() => { localStorage.clear(); }). Cada teste precisa começar **vazio** para ser **independente**: o resultado não pode depender de outro teste nem da ordem de execução.', 'Palavras-chave: afterEach (ou beforeEach); localStorage.clear; independente; ordem. Nota cheia (0,4): onde fica + por quê. Metade (0,2): só uma das partes. Zero (0): sugere juntar os dois testes.'),
      (v_atividade, 10, 1, 'Escreva o comando que roda uma vez só os testes do arquivo fluxoLogin e diga o que é executar os testes (7.3).', 0.2, 'npx vitest run fluxoLogin — Executar os testes (7.3) é **rodar a suíte e registrar o resultado de cada caso**: passou, falhou ou foi pulado.', 'Palavras-chave: npx vitest run fluxoLogin; rodar e registrar passou/falhou/pulado. Nota cheia (0,2): comando + definição. Metade (0,1): só um dos dois. Zero (0): comando de outra ferramenta.'),
      (v_atividade, 10, 2, 'Explique o que ler no resumo da execução e, quando um teste falha, o que ler na mensagem (esperado × recebido e o trecho do DOM).', 0.4, 'No resumo: **quantos arquivos e testes passaram** (e falharam) e o **tempo total**. No teste que falha: a mensagem com o **valor esperado × o valor recebido** e o **trecho do DOM** que a Testing Library imprime, para ver o que realmente estava na tela.', 'Palavras-chave: arquivos e testes que passaram; tempo; esperado × recebido; trecho do DOM. Nota cheia (0,4): resumo + leitura da falha. Metade (0,2): só uma das partes. Zero (0): diz que basta ver se ficou verde.'),
      (v_atividade, 10, 3, 'Explique por que rodar a suíte 3 vezes e o que fazer com um teste cujo resultado muda sem mudança no código.', 0.4, 'Rodar **3 vezes** mostra se o resultado é **estável**: se muda **sem mudança no código**, o teste é **instável (flaky)**. Esse teste entra na **lista de correção** (procurar espera fixa, dependência entre testes ou API real) e não pode ser ignorado.', 'Palavras-chave: 3 vezes; resultado muda sem mudar o código; instável; lista de correção. Nota cheia (0,4): motivo + o que fazer. Metade (0,2): só uma das partes. Zero (0): sugere apagar ou pular o teste.');
end $$;
